 */
@Test
public void verifyServerNameCollisionInNewWizard() {
    // Showing view
    serversViewBot.show();
    // Verifying the servers count is 0
    assertEquals(0, getCoreServersCount());
    assertEquals(0, serversViewBot.getServersCount());
    // Opening wizard
