    assertTrue(browserViewBot.existsEntry("DIT", "Root DSE", "ou=system", "ou=users", "l=eu + l=de + l=Berlin + l=Brandenburger Tor"));
    browserViewBot.selectEntry("DIT", "Root DSE", "ou=system", "ou=users", "l=eu + l=de + l=Berlin + l=Brandenburger Tor");
    // expand entry and verify child is visible
    browserViewBot.expandEntry("DIT", "Root DSE", "ou=system", "ou=users", "l=eu + l=de + l=Berlin + l=Brandenburger Tor");
